from collections import deque

def count_5_regions(block):
    rows = len(block)
    cols = len(block[0])
    visited = [[False]*cols for _ in range(rows)]
    regions = 0

    for i in range(rows):
        for j in range(cols):
            if block[i][j] == 5 and not visited[i][j]:
                regions += 1
                # BFS
                queue = deque([(i, j)])
                visited[i][j] = True
                while queue:
                    ri, rj = queue.popleft()
                    for di, dj in [(-1,0), (1,0), (0,-1), (0,1)]:
                        ni, nj = ri+di, rj+dj
                        if 0 <= ni < rows and 0 <= nj < cols and block[ni][nj] == 5 and not visited[ni][nj]:
                            visited[ni][nj] = True
                            queue.append((ni, nj))
    return regions

